import {
  IHikingObstacleBaseDTO,
  IHikingObstaclesListWithHikingDTO,
  IHikingObstaclesListWithObstacleDTO,
} from './../@types/DTO/hikingObstacles.dto.types';
import { mapObstacleDTOToFront } from '../../Obstacles/@mappers/obstacles.toFront.mapper';
import { IHikingObstacleOneDTO } from '../@types/DTO/hikingObstacles.dto.types';
import {
  IHikingObstacleBase,
  IHikingObstacleOne,
  IHikingObstacleWithHikingListItem,
  IHikingObstacleWithObstacleListItem,
} from '../@types/hikingObstacles.types';

const mapHikingObstacleBase = (backData: IHikingObstacleBaseDTO): IHikingObstacleBase => {
  return {
    id: +backData.id,
    description: backData.description,
    description_in: backData.description_in,
    description_out: backData.description_out,
    date_in: new Date(backData.date_in),
    date_out: new Date(backData.date_out),
    idHikingTrack: +backData.id_hiking_track,
    last_photo_preview: backData.last_photo_preview,
    created: {
      date: new Date(backData.created_at),
      user: {
        id: +backData.creator_id,
        name: backData.creator_name,
        surname: backData.creator_surname,
        photo: backData.creator_photo,
      },
    },
    updated:
      backData.updated_id &&
      backData.updated_at &&
      backData.updated_name &&
      backData.updated_surname &&
      backData.updated_photo
        ? {
            date: new Date(backData.updated_at),
            user: {
              id: +backData.updated_id,
              name: backData.updated_name,
              surname: backData.updated_surname,
              photo: backData.updated_photo,
            },
          }
        : null,
  };
};

export const mapHikingObstacleListItem = (
  backData: IHikingObstaclesListWithObstacleDTO,
): IHikingObstacleWithObstacleListItem => {
  return {
    ...mapHikingObstacleBase(backData),

    obstacle: mapObstacleDTOToFront({
      id: backData.obstacle_id,
      name: backData.obstacle_name,
      description: backData.obstacle_description,
      lat: backData.obstacle_lat,
      lon: backData.obstacle_lon,
      altitude: backData.obstacle_altitude,
      link: backData.obstacle_link,
      comment: backData.obstacle_comment,
      type: backData.obstacle_type,
      category: backData.obstacle_category,

      created_at: '0',
      creator_id: '',
      creator_name: '',

      updated_at: null,
      updator_id: null,
      updator_name: null,

      geo_region_id: backData.obstacle_geo_region_id,
      geo_region_name: backData.obstacle_geo_region_name,
    }),
  };
};

export const mapHikingObstacleWithHiking = (
  backData: IHikingObstaclesListWithHikingDTO,
): IHikingObstacleWithHikingListItem => {
  return {
    ...mapHikingObstacleBase(backData),
    hiking: {
      id: +backData.id_hiking,
      name: backData.hiking_name,
      ava: backData.hiking_ava,
      start: new Date(backData.hiking_start),
      finish: new Date(backData.hiking_finish),
    },
  };
};

export const mapHikingObstacleOne = (backData: IHikingObstacleOneDTO): IHikingObstacleOne => {
  return {
    id: +backData.id,
    description: backData.description,
    description_in: backData.description_in,
    description_out: backData.description_out,
    date_in: new Date(backData.date_in),
    date_out: new Date(backData.date_out),
    idHikingTrack: +backData.id_hiking_track,
    last_photo_preview: backData.photos?.[0]?.url_preview ?? null,
    obstacle: mapObstacleDTOToFront(backData.obstacle),
    members: backData.members.map((m) => {
      return {
        id: +m.id,
        user: {
          id: +m.user_id,
          name: m.user_name,
          surname: m.user_surname,
          photo: m.user_photo,
        },
      };
    }),
    photos: backData.photos.map((p) => {
      return {
        id: +p.id,
        url_preview: p.url_preview,
        url: p.url,
        date: new Date(p.date),
        comment: p.comment,
        coordinates: p.lon && p.lat ? [+p.lat, +p.lon, parseInt(p.altitude ?? '0')] : null,
        created: {
          date: new Date(p.created_at),
          user: {
            id: +p.creator_id,
            name: p.creator_name,
            surname: p.creator_surname,
            photo: p.creator_photo,
          },
        },
      };
    }),
    created: {
      date: new Date(backData.created_at),
      user: {
        id: +backData.creator_id,
        name: backData.creator_name,
        surname: backData.creator_surname,
        photo: backData.creator_photo,
      },
    },
    updated:
      backData.updated_id &&
      backData.updated_at &&
      backData.updated_name &&
      backData.updated_surname &&
      backData.updated_photo
        ? {
            date: new Date(backData.updated_at),
            user: {
              id: +backData.updated_id,
              name: backData.updated_name,
              surname: backData.updated_surname,
              photo: backData.updated_photo,
            },
          }
        : null,
  };
};
